/**
 * Prepare parsed rows for import.
 *
 * `amount` is an integer number of cents, not a decimal string.
 * `today` is a calendar date in YYYY-MM-DD format.
 *
 * Deduplication applies within this batch; existing ledger transactions
 * cannot be checked because they are not supplied to this function.
 */
export function importRows(rows, today) {
	function isValidDate(value) {
		if (
			typeof value !== "string" ||
			value.length !== 10 ||
			!/^\d{4}-\d{2}-\d{2}$/.test(value)
		) {
			return false;
		}

		const date = new Date(`${value}T00:00:00.000Z`);
		return (
			!Number.isNaN(date.getTime()) &&
			date.toISOString().slice(0, 10) === value
		);
	}

	if (!Array.isArray(rows)) {
		throw new Error("ledger: import rows must be an array");
	}
	if (!isValidDate(today)) {
		throw new Error("ledger: today must be a valid date in YYYY-MM-DD format");
	}

	const importedRows = [];
	const warnings = [];
	const seen = new Set();
	let skipped = 0;
	let deduplicated = 0;

	for (let i = 0; i < rows.length; i++) {
		const row = rows[i];
		const rowNumber = i + 1;

		if (!row || typeof row !== "object" || Array.isArray(row)) {
			throw new Error(`ledger: invalid import row ${rowNumber}`);
		}
		if (!isValidDate(row.date)) {
			throw new Error(`ledger: invalid date in import row ${rowNumber}`);
		}
		if (typeof row.payee !== "string" || row.payee.trim() === "") {
			throw new Error(`ledger: invalid payee in import row ${rowNumber}`);
		}
		if (!Number.isSafeInteger(row.amount)) {
			throw new Error(
				`ledger: amount in import row ${rowNumber} must be safe integer cents`,
			);
		}
		if (row.memo != null && typeof row.memo !== "string") {
			throw new Error(`ledger: invalid memo in import row ${rowNumber}`);
		}

		if (row.date > today) {
			skipped++;
			warnings.push(
				`ledger: skipping future-dated import row ${rowNumber} (${row.date})`,
			);
			continue;
		}

		const amount = row.amount === 0 ? 0 : row.amount;
		const key = JSON.stringify([row.date, amount, row.payee]);

		if (seen.has(key)) {
			deduplicated++;
			continue;
		}
		seen.add(key);

		importedRows.push({
			...row,
			amount,
			memo:
				row.memo == null || row.memo.trim() === ""
					? row.payee
					: row.memo,
		});
	}

	return {
		rows: importedRows,
		imported: importedRows.length,
		skipped,
		deduplicated,
		warnings,
	};
}
